import {entries,availableEffects} from './catalog.mjs';
import {obstacles} from './core.mjs';
import {request} from './cloud-ui.mjs';
const $=s=>document.querySelector(s),atlas=new Image();atlas.src='sprites.png';
const categories=[['all','Tout'],['personnage','Personnage'],['ennemis','Ennemis'],['boss','Boss'],['objets','Objets'],['salles','Salles']];let category='all';
const el=(tag,cls,text)=>{const e=document.createElement(tag);if(cls)e.className=cls;if(text!==undefined)e.textContent=text;return e};
$('#total-count').textContent=`${entries.length} entrées`;
for(const [id,name]of categories){const button=el('button',null,name),count=entries.filter(e=>id==='all'||e.category===id).length;button.type='button';button.append(el('small',null,count));button.dataset.category=id;button.setAttribute('aria-pressed',String(id===category));button.onclick=()=>{category=id;for(const b of $('#filters').children)b.setAttribute('aria-pressed',String(b.dataset.category===id));draw()};$('#filters').append(button)}
function drawArt(canvas,entry){const c=canvas.getContext('2d');c.clearRect(0,0,canvas.width,canvas.height);if(entry.sprite!==undefined){if(!atlas.complete||!atlas.naturalWidth)return;const half=atlas.naturalWidth/2;c.drawImage(atlas,(entry.sprite%2)*half,Math.floor(entry.sprite/2)*half,half,half,0,0,canvas.width,canvas.height);return}c.save();c.scale(canvas.width/960,canvas.height/600);c.fillStyle='#2c382e';c.fillRect(0,0,960,600);c.strokeStyle='#39493a';c.lineWidth=2;for(let y=0;y<600;y+=60)for(let x=0;x<960;x+=60)c.strokeRect(x,y,60,60);c.strokeStyle='#6f8060';c.lineWidth=22;c.strokeRect(25,25,910,550);c.fillStyle='#111a15';for(const[x,y,w,h]of[[430,0,100,40],[430,560,100,40],[0,250,40,100],[920,250,40,100]])c.fillRect(x,y,w,h);for(const o of obstacles(entry.room)){c.fillStyle='#17231a';c.fillRect(o.x+8,o.y+8,o.w,o.h);c.fillStyle='#657557';c.fillRect(o.x,o.y,o.w,o.h)}if(entry.room==='treasure'){c.fillStyle='#dfb77b';c.font='110px serif';c.textAlign='center';c.textBaseline='middle';c.fillText('◇',480,300)}if(entry.room==='start'){c.fillStyle='#aec9a1';c.beginPath();c.arc(480,300,24,0,Math.PI*2);c.fill()}if(entry.room==='boss'){c.strokeStyle='#b37a64';c.lineWidth=8;c.beginPath();c.arc(480,300,95,0,Math.PI*2);c.stroke();c.fillStyle='#b37a64';for(let a=0;a<Math.PI*2;a+=Math.PI/4){c.beginPath();c.arc(480+Math.cos(a)*150,300+Math.sin(a)*150,10,0,Math.PI*2);c.fill()}}c.restore()}
function draw(){const query=$('#search').value.trim().toLocaleLowerCase('fr'),visible=entries.filter(e=>(category==='all'||e.category===category)&&[e.name,e.kind,e.description,e.details].join(' ').toLocaleLowerCase('fr').includes(query));$('#result-count').textContent=`${visible.length} ${visible.length===1?'entrée':'entrées'} affichée${visible.length===1?'':'s'}`;$('#empty-results').hidden=!!visible.length;$('#entries').replaceChildren();for(const entry of visible){const card=el('article','entry'),art=el('div','entry-art');art.append(el('span','entry-number',String(entries.indexOf(entry)+1).padStart(2,'0')),el('span','entry-type',entry.kind));if(entry.icon)art.append(el('span','item-glyph',entry.icon));else{const canvas=el('canvas',entry.room?'room-preview':'');canvas.width=entry.room?430:240;canvas.height=entry.room?276:240;canvas.setAttribute('role','img');canvas.setAttribute('aria-label',entry.name);art.append(canvas);drawArt(canvas,entry);if(!atlas.complete)atlas.addEventListener('load',()=>drawArt(canvas,entry),{once:true})}const body=el('div','entry-body');body.append(el('h2',null,entry.name),el('p',null,entry.description));const stats=el('dl','entry-stats');for(const[label,value]of entry.stats){const row=el('div');row.append(el('dt',null,label),el('dd',null,value));stats.append(row)}const details=el('details'),summary=el('summary',null,'Comportement et détails');details.append(summary,el('p',null,entry.details));body.append(stats,details);card.append(art,body);$('#entries').append(card)}}
$('#search').addEventListener('input',draw);draw();
for(const effect of availableEffects){const card=el('div','effect-chip'),text=el('div');text.append(el('strong',null,effect.label),el('small',null,effect.inPrototype?'Dans le donjon de test':'Disponible pour le générateur'));card.append(el('span',null,effect.icon),text);$('#effects-list').append(card)}
async function status(){try{const state=await request('/api/status');$('#connection-status').textContent=state.configured?'Une clé est déjà enregistrée. Vous pouvez la remplacer ci-dessous.':'Aucune clé enregistrée. Collez votre clé pour activer la génération distante.';$('#cloud-model').value=state.model;$('#model-label').textContent=`${state.model} · calcul distant`;return state}catch(e){$('#connection-status').textContent=e.message}}
$('#open-settings').onclick=()=>{$('#cloud-settings').showModal();status()};
$('#cloud-settings').addEventListener('close',()=>{$('#api-key').value=''});
$('#key-form').onsubmit=async e=>{e.preventDefault();const button=e.target.querySelector('button');button.disabled=true;let key=$('#api-key').value;$('#api-key').value='';try{const result=await request('/api/config',{method:'POST',body:{key,model:$('#cloud-model').value}});key='';$('#connection-status').textContent='Clé enregistrée dans le serveur local. La connexion sera vérifiée à la première génération.';$('#model-label').textContent=`${result.model} · calcul distant`}catch(err){$('#connection-status').textContent=err.message}finally{key='';button.disabled=false}};
if(location.hash==='#connexion'){$('#cloud-settings').showModal();status()}
